func TestScaleIngredientView_preserves_raw_ingredient(t *testing.T) {
	ing := store.IngredientRow{
		Name:          "flour",
		Quantity:      "2 cups",
		Note:          "all-purpose",
		RawIngredient: "2 cups flour (all-purpose)",
	}
	result := scaleIngredientView(ing, 2.0)

	if result.Name != "flour" {
		t.Errorf("name = %q, want \"flour\"", result.Name)
	}
	if result.RawIngredient != "2 cups flour (all-purpose)" {
		t.Errorf("raw_ingredient = %q, want unchanged", result.RawIngredient)
	}
	if result.FormContext != "raw" {
		t.Errorf("form_context = %q, want \"raw\"", result.FormContext)
	}
	// Scaled quantity should double the numeric part.
	if result.ScaledQuantity != "4 cups" {
		t.Errorf("scaled_quantity = %q, want \"4 cups\"", result.ScaledQuantity)
	}
}

