func TestPricingSummaryView_serialization(t *testing.T) {
	ps := pricingSummaryView{
		TotalAvailablePrices: 12.50,
		MissingPriceCount:    3,
		AvailablePrices: []priceInfoView{
			{ItemName: "flour", Amount: 3.50, StoreName: "Walmart"},
			{ItemName: "sugar", Amount: 4.00, StoreName: "Walmart"},
			{ItemName: "butter", Amount: 5.00, StoreName: "Walmart"},
		},
	}

	// Verify total matches sum.
	var total float64
	for _, p := range ps.AvailablePrices {
		total += p.Amount
	}
	if math.Abs(total-ps.TotalAvailablePrices) > 0.01 {
		t.Errorf("total = %.2f, want %.2f", ps.TotalAvailablePrices, total)
	}
	if ps.MissingPriceCount != 3 {
		t.Errorf("missing_price_count = %d, want 3", ps.MissingPriceCount)
	}
}

